    // do elm & - elm. isolate LSB of elm_size. that bit is largest pow of 2 that divides elm_size
    size_t lowbit = elm_size & (~elm_size + 1);
    return lowbit < WC_MAX_ALIGN ? lowbit : WC_MAX_ALIGN; // clamp to max align
